#!/usr/bin/env bash
# Crée les labels, jalons et issues du projet SHS. Prérequis : GitHub CLI (`gh auth login`), être dans le dépôt cloné.
set -euo pipefail
cd "$(dirname "$0")/.."
ASSIGNEE_A="asmaaaa01ab"
ASSIGNEE_B="fatimazohraaalilouch-dev"
ASSIGNEE_C="zinebs_dev"
for v in "$ASSIGNEE_A" "$ASSIGNEE_C"; do
  case "$v" in REMPLACER*) echo "Renseignez ASSIGNEE_A et ASSIGNEE_C en haut du script."; exit 1;; esac
done
REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner)
echo "Dépôt : $REPO"

echo "== Labels"
mk() { gh label create "$1" --color "$2" --description "$3" --force >/dev/null; }
mk lot:A 0F766E "Annonces et justificatif"
mk lot:B 1D4ED8 "Recherche et classement"
mk lot:C 7C3AED "Réservation, messagerie, Copilot"
mk shared 6B7280 "Tâche commune"
mk android 3DDC84 "App Android"
mk backend B45309 "Spring Boot"
mk intelligence DB2777 "Service FastAPI"
mk infra 0369A1 "Docker, CI, dépôt"
mk xml 0EA5E9 "Écran XML fidèle à la maquette"
mk docs 94A3B8 "Documentation"
mk decision F59E0B "Décision à prendre"
mk ecart DC2626 "Écart maquette / règle métier"
mk bloquant B91C1C "Bloque les autres"
mk p1 DC2626 "Indispensable à la démo"
mk p2 F59E0B "Important"
mk p3 9CA3AF "À sacrifier en premier"

echo "== Jalons"
ms() { gh api "repos/$REPO/milestones" -f title="$1" -f due_on="$2T23:59:59Z" >/dev/null 2>&1 || echo "(jalon existant : $1)"; }
ms "S1 · Fondations (J1–J7, → 17/11)" "2026-11-17"
ms "S2 · Parcours de base (J8–J14, → 24/11)" "2026-11-24"
ms "S3 · Intelligence et écrans avancés (J15–J21, → 01/12)" "2026-12-01"
ms "S4 · Finitions et livraison (J22–J30, → 10/12)" "2026-12-10"

echo "== Issues"
