gh issue create --title "[S1-02] Android : synchro Gradle, build debug, lancement sur émulateur" --body-file ".github/issues/S1-02.md" --label "android,bloquant,p1,lot:B" --milestone "S1 · Fondations (J1–J7, → 17/11)" --assignee "$ASSIGNEE_B"
gh issue create --title "[S1-03] Docker Compose : db + api + intelligence démarrent, Flyway applique V1–V2" --body-file ".github/issues/S1-03.md" --label "infra,backend,bloquant,p1,lot:C" --milestone "S1 · Fondations (J1–J7, → 17/11)" --assignee "$ASSIGNEE_C"
